package android.graphics; import java.awt.image.*;public class Bitmap {public enum Config {ARGB_8888} public BufferedImage image;public static Bitmap createBitmap(int w,int h,Config c){Bitmap b=new Bitmap();b.image=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);return b;}public static Bitmap createBitmap(int[] p,int w,int h,Config c){Bitmap b=createBitmap(w,h,c);b.setPixels(p,0,w,0,0,w,h);return b;}public void setPixels(int[] pixels,int offset,int stride,int x,int y,int w,int h){image.setRGB(x,y,w,h,pixels,offset,stride);}}